float oct(vec3 p){
    return fract(4768.1232345456 * sin((p.x+p.y*43.0+p.z*137.0)));
}

vec3 hash( vec3 p )
{
     return vec3(oct(p), oct(p + 13.37), oct(p + 42.0));
}

