float voronoi( in vec3 x )
{
    vec3 n = floor( x );
    vec3 f = fract( x );

	vec4 m = vec4( 8.0 );
    for( int j=-1; j<=1; j++ )
    for( int i=-1; i<=1; i++ )
    for( int h=-1; h<=1; h++ )
    {
        vec3  g = vec3(float(i), float(j), float(h));
        vec3  o = hash( n + g );
        vec3  r = g - f + o;
		float d = dot( r, r );
        m = mix(m, vec4( d, o ), step(d, m.x));
    }

    return 1.0 - m.r;
}

float snow(vec2 uv){
    float sum = 0.0;
    float scale = 15.0;
    for(int i=0;i < 10;i++){
        vec2 coord2d = uv * scale + 15.0 * iTime;
        vec3 coord3d = vec3(coord2d, iTime * 0.15);
        sum += smoothstep(0.95, 1.0, voronoi(coord3d));
        scale *= 1.5;
    }
    return sum;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
	vec2 uv = fragCoord.xy / iResolution.xy;
    uv.y *= iResolution.y / iResolution.x;

    uv.x += 10.0;
    float a = snow(uv);

	fragColor = vec4(a, a, a, 1.0);
}
